import { ReactNode, FC } from 'react';

interface TabBarItem {
    /** 标签键 */
    key: string;
    /** 标题 */
    title: string;
    /** 图标 */
    icon: ReactNode;
    /** 选中图标 */
    activeIcon?: ReactNode;
    /** 徽标 */
    badge?: number | string;
    /** 是否显示红点 */
    dot?: boolean;
}
interface TabBarProps {
    /** 当前选中 */
    activeKey?: string;
    /** 默认选中 */
    defaultActiveKey?: string;
    /** 标签项 */
    items: TabBarItem[];
    /** 切换回调 */
    onChange?: (key: string) => void;
    /** 是否固定在底部 */
    fixed?: boolean;
    /** 是否显示上边框 */
    bordered?: boolean;
    /** 安全区适配 */
    safeArea?: boolean;
    /** 自定义类名 */
    className?: string;
}

declare const TabBar: FC<TabBarProps>;

export { TabBar, TabBar as default };
export type { TabBarItem, TabBarProps };
